    expect(firstStatus).toBe('needs_approval');
    expect(calls).toEqual({
      ingest: 1,
      edit: 1,
      verify: 1,
      script: 1,
      ground: 1,
      voice: 1,
      render: 1,
      review: 1,
      gate: 1,
    });

    recut(db, id, 'make it punchier');

    expect(getRun(db, id).status).toBe('running');
